with feeders as (
    select
        md5(upper('HUB_AGREEMENT|' || (HUB_AGREEMENT_BK__HOSID))) as HUB_AGREEMENT_HK
        , DATE_OF_SUP as EMPANELMENT_SUPPORT_DATE
        , cast(null as varchar) as COST_NEGOTIATED_INDICATOR
        , 'BJAZ_HM_HOSPITAL_MASTER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hospital_master') }}
    where (nullif(trim(HOSID),'')) is not null
    union all
    select
        md5(upper('HUB_AGREEMENT|' || (HUB_AGREEMENT_BK__HOSID))) as HUB_AGREEMENT_HK
        , cast(null as varchar) as EMPANELMENT_SUPPORT_DATE
        , COSTNEGO as COST_NEGOTIATED_INDICATOR
        , 'BJAZ_HM_HOSP_MASTER_EXTN1' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hosp_master_extn1') }}
    where (nullif(trim(HOSID),'')) is not null
),

resolved as (
    select
        HUB_AGREEMENT_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then EMPANELMENT_SUPPORT_DATE end) as EMPANELMENT_SUPPORT_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then COST_NEGOTIATED_INDICATOR end) as COST_NEGOTIATED_INDICATOR,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_AGREEMENT_HK
),

hashed as (
    select
        *,
        case when EMPANELMENT_SUPPORT_DATE is not null or COST_NEGOTIATED_INDICATOR is not null
                     then md5(upper(coalesce(cast(EMPANELMENT_SUPPORT_DATE as varchar), '') || '|' || coalesce(cast(COST_NEGOTIATED_INDICATOR as varchar), '')))
                end as SAT_AGREEMENT_DEFINITION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_AGREEMENT_HK is not null
  and SAT_AGREEMENT_DEFINITION_HASHDIFF is not null
